<script lang="ts">
 import { tick } from 'svelte';import type { Chapter,ChoicePath,FollowUp } from '$lib/types/chapter';import PerspectiveAttunement from './PerspectiveAttunement.svelte';import PrivateFieldNote from './PrivateFieldNote.svelte';
 let { chapter,choice,onretry }:{chapter:Chapter;choice:ChoicePath;onretry:()=>void}=$props();let followIndex:number|null=$state(null);let follow=$derived(followIndex===null?null:choice.followUps[followIndex]);let comparisonOpen=$state(false);let heading:HTMLElement;let currentFieldState=$derived(follow?.state??choice.fieldState);let position=$derived(follow?.position??choice.position);
 $effect(()=>{choice.id;followIndex=null;tick().then(()=>heading?.focus())});
</script>
